#!/bin/sh
shells_menu(){ while :; do c=$(ui_menu Shells 'Install and configure command shells.' wizards 'Selectable shell configuration wizards' scan 'Show installed shells' install 'Install shells' default 'Change login shell' bash 'Configure Bash' zsh 'Configure Zsh' ash 'Configure Ash' aliases 'Edit shared aliases' prompt 'Install/configure Starship' path 'Configure PATH' history 'Configure history defaults' config 'Shell configuration center' plugins 'Plugin and framework manager') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in wizards) shell_wizards_menu;; scan) ui_text Shells "$(grep -v '^#' /etc/shells 2>/dev/null; for x in sh ash bash zsh fish dash mksh ksh nu; do have "$x" && command -v "$x"; done|sort -u)";; install) p=$(ui_input Shells 'Packages to install:' 'bash zsh fish mksh') || continue; run_capture Shells pkg_install $p;; default) s=$(ui_input 'Login shell' 'Executable path:' "$(command -v bash 2>/dev/null || command -v sh)") || continue; grep -Fqx "$s" /etc/shells 2>/dev/null || printf '%s\n' "$s"|as_root tee -a /etc/shells >/dev/null; run_capture chsh as_root chsh -s "$s" "$CURRENT_USER";; bash) ensure_template bashrc "$CURRENT_HOME/.bashrc";; zsh) ensure_template zshrc "$CURRENT_HOME/.zshrc";; ash) ensure_template ashrc "$CURRENT_HOME/.ashrc"; replace_block "$CURRENT_HOME/.profile" ash 'export ENV="$HOME/.ashrc"';; aliases) ensure_template aliases "$CURRENT_HOME/.aliases";; prompt) starship_menu;; path) replace_block "$CURRENT_HOME/.profile" path '[ -d "$HOME/bin" ] && PATH="$HOME/bin:$PATH"\n[ -d "$HOME/.local/bin" ] && PATH="$HOME/.local/bin:$PATH"\nexport PATH';; history) replace_block "$CURRENT_HOME/.bashrc" history 'HISTCONTROL=ignoreboth:erasedups\nHISTSIZE=5000\nHISTFILESIZE=10000\nshopt -s histappend';; config) shell_config_center;; plugins) plugin_manager_menu shell;; esac; done; }
starship_menu(){ c=$(ui_menu Starship 'Prompt manager.' install 'Install Starship' config 'Generate/edit config' bash 'Enable for Bash' zsh 'Enable for Zsh' fish 'Enable for Fish') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in install) run_capture Starship pkg_install starship;; config) ensure_template starship "$CURRENT_HOME/.config/starship.toml";; bash) replace_block "$CURRENT_HOME/.bashrc" starship 'command -v starship >/dev/null 2>&1 && eval "$(starship init bash)"';; zsh) replace_block "$CURRENT_HOME/.zshrc" starship 'command -v starship >/dev/null 2>&1 && eval "$(starship init zsh)"';; fish) mkdir -p "$CURRENT_HOME/.config/fish/conf.d"; write_file "$CURRENT_HOME/.config/fish/conf.d/starship.fish" 644 'command -q starship; and starship init fish | source';; esac; }
